import{_ as o,C as t,o as a,c as d,ag as i,E as c}from"./chunks/framework.cyF4XceO.js";const _=JSON.parse('{"title":"バージョンと互換性","description":"","frontmatter":{},"headers":[],"relativePath":"ja/docs/versions.md","filePath":"ja/docs/versions.md"}'),s={name:"ja/docs/versions.md"};function l(n,e,m,f,u,h){const r=t("StatusNote");return a(),d("div",null,[e[0]||(e[0]=i('<h1 id="バージョンと互換性" tabindex="-1">バージョンと互換性 <a class="header-anchor" href="#バージョンと互換性" aria-label="Permalink to &quot;バージョンと互換性&quot;">​</a></h1><p>Takoform の current version stream は Host API、各 Form definition、Core/library software、Provider software の4つです。各軸は独立しており、Form Package の API identifier は wire/envelope format であって product の5つ目の release stream ではありません。</p><h2 id="current-publisher-corpus" tabindex="-1">Current publisher corpus <a class="header-anchor" href="#current-publisher-corpus" aria-label="Permalink to &quot;Current publisher corpus&quot;">​</a></h2><p>現在の official corpus は versionless family <code>edge.forms.takoform.com</code> 一つです。exact な Experimental <code>0.x</code> Form は16個、Interface は7個、Binding は6個です。正本は <a href="https://github.com/tako0614/takoform-forms/tree/3a395e4d7f9f652a942da52905857fccc41b467e" target="_blank" rel="noreferrer"><code>takoform-forms</code> commit <code>3a395e4</code>（英語のみ）</a> に固定されています。</p><table tabindex="0"><thead><tr><th>軸</th><th>現在の identity</th><th>意味</th></tr></thead><tbody><tr><td>Host API</td><td><strong><code>forms.takoform.com/v1</code></strong></td><td>discovery、exact Form availability、operation、fence、error の stable wire contract。</td></tr><tr><td>Form</td><td>各 Form の <strong><code>definitionVersion</code></strong></td><td>独立した exact contract。公式 corpus は Edge16。</td></tr><tr><td>Core/library</td><td>独立した software SemVer</td><td>SDK、verifier、compiler、CLI の release。</td></tr><tr><td>Provider</td><td>独立した software SemVer</td><td>明示的に対応する official Form の typed tooling。</td></tr><tr><td>Form Package</td><td><strong><code>packages.forms.takoform.com/v1alpha5</code></strong></td><td>data envelope / wire format。product version 軸ではない。</td></tr></tbody></table><p>canonical Registry Provider は official-Forms-only です。第三者 package は同じ Host API path と package/verification contract を使い、自分の namespace の明示的な Provider mapping で配布します。module は official Takoform Provider と他の Takoform / industry-standard Provider を組み合わせられます。</p><h2 id="provider-release-と-publication-boundary" tabindex="-1">Provider release と publication boundary <a class="header-anchor" href="#provider-release-と-publication-boundary" aria-label="Permalink to &quot;Provider release と publication boundary&quot;">​</a></h2><p>Provider <code>3.0.0</code> は Registry 公開済み実装ですが、8 family / 31 resource projection は その release に固定された履歴であり、current publisher corpus ではありません。Edge16 の official-only mapping は次 major candidate（未公開）です。<code>&gt;=3.1.0</code> の例も candidate / unpublished であり、release record が変わるまで install を主張しません。</p><table tabindex="0"><thead><tr><th>Distribution</th><th>Host API</th><th>Form projection</th><th>状態</th></tr></thead><tbody><tr><td>Provider 3.0.0</td><td>Host API v1</td><td>履歴の 8 family / 31 resource projection</td><td>公開済み Registry artifact。current roster ではない。</td></tr><tr><td>Future official-only Provider</td><td>Host API v1</td><td>current Edge16 publisher corpus</td><td>次 major candidate。未公開・install 不可。</td></tr><tr><td>Provider 2.1.1</td><td>Host API v1beta1</td><td>retained Edge v1beta1 identities</td><td>不変の履歴 client。exact pin のみ。</td></tr><tr><td>Provider 2.0.0 / 1.0.3</td><td>撤回済み pre-Beta epoch</td><td>retired identity</td><td>recovery / migration 用の履歴。</td></tr></tbody></table><h2 id="current-edge-form-links-詳細は英語のみ" tabindex="-1">Current Edge Form links（詳細は英語のみ） <a class="header-anchor" href="#current-edge-form-links-詳細は英語のみ" aria-label="Permalink to &quot;Current Edge Form links（詳細は英語のみ）&quot;">​</a></h2><ul><li><a href="/docs/resources/module_worker.html"><code>takoform_module_worker</code>（英語のみ）</a></li><li><a href="/docs/resources/worker_bundle.html"><code>takoform_worker_bundle</code>（英語のみ）</a></li><li><a href="/docs/resources/static_asset_bundle.html"><code>takoform_static_asset_bundle</code>（英語のみ）</a></li><li><a href="/docs/resources/worker_version.html"><code>takoform_worker_version</code>（英語のみ）</a></li><li><a href="/docs/resources/worker_deployment.html"><code>takoform_worker_deployment</code>（英語のみ）</a></li><li><a href="/docs/resources/worker_custom_domain.html"><code>takoform_worker_custom_domain</code>（英語のみ）</a></li><li><a href="/docs/resources/worker_endpoint.html"><code>takoform_worker_endpoint</code>（英語のみ）</a></li><li><a href="/docs/resources/worker_cron_trigger.html"><code>takoform_worker_cron_trigger</code>（英語のみ）</a></li><li><a href="/docs/resources/edge_kv_namespace.html"><code>takoform_edge_kv_namespace</code>（英語のみ）</a></li><li><a href="/docs/resources/sqlite_database.html"><code>takoform_sqlite_database</code>（英語のみ）</a></li><li><a href="/docs/resources/sqlite_migration_set.html"><code>takoform_sqlite_migration_set</code>（英語のみ）</a></li><li><a href="/docs/resources/sqlite_migration_application.html"><code>takoform_sqlite_migration_application</code>（英語のみ）</a></li><li><a href="/docs/resources/at_least_once_queue.html"><code>takoform_at_least_once_queue</code>（英語のみ）</a></li><li><a href="/docs/resources/queue_consumer.html"><code>takoform_queue_consumer</code>（英語のみ）</a></li><li><a href="/docs/resources/durable_workflow.html"><code>takoform_durable_workflow</code>（英語のみ）</a></li><li><a href="/docs/resources/actor_namespace.html"><code>takoform_actor_namespace</code>（英語のみ）</a></li></ul><h2 id="specification-receipt-と撤回-lane" tabindex="-1">Specification receipt と撤回 lane <a class="header-anchor" href="#specification-receipt-と撤回-lane" aria-label="Permalink to &quot;Specification receipt と撤回 lane&quot;">​</a></h2><p>Specification 1.0/1.1 receipt は archive evidence であり、current version lane では ありません。API v1.1、Form <code>1.0.0</code>、Provider release を mint しません。撤回された Host API epoch と Provider client は exact pin による recovery / migration のためにのみ 履歴として残ります。<a href="/release/">履歴 release</a> と <a href="/release/migrations/v2-to-v3.html">v2 から v3 への移行境界</a> （英語のみ）を参照してください。</p>',13)),c(r)])}const k=o(s,[["render",l]]);export{_ as __pageData,k as default};
